// Multi-perspective replays, part 2: the remaining 13 Hall case files × 5 lenses.
// Extends the shared registries in quests_replay.js (REPLAY_QUESTS, REPLAYS, REPLAY_IDS, REPLAY_ANSWERS).
// Every calculation input is a Simulation Assumption and is labelled as such in the question; facts quoted in
// dialogue come from the case file. The Keyrus file uses public information only and fictional numbers.
import { LENSES, LENS_ORDER, REPLAY_QUESTS, REPLAYS, REPLAY_IDS, REPLAY_ANSWERS, replayBase, replayFb } from './quests_replay.js';

const r1 = (x) => Math.round(x * 10) / 10;
const r2 = (x) => Math.round(x * 100) / 100;
const SIM = '[Simulation Assumption] ';

/**
 * Compact deal definition → five replay quests.
 * lens: { t: title, s: summary, say, n: [concept, question, answer, tol, unit, [vi, en, why, impl, related]], q: [concept, question, opts, correctIdx, [vi, en, why, impl, related]], map: [ask, takeaway] }
 */
function deal(key, caseId, req, short, roles, lenses) {
  const quests = {}, map = {};
  for (const l of LENS_ORDER) {
    const d = lenses[l], id = `r_${key}_${l}`, review = `${short} — ${LENSES[l].name}`;
    const [nc, nq, na, ntol, nunit, nfb] = d.n, [qc, qq, qopts, qa, qfb] = d.q;
    REPLAY_ANSWERS[`${key}_${l}`] = na;
    REPLAY_QUESTS.push({
      ...replayBase(id, caseId, l, `${short} qua lăng kính ${LENSES[l].name}`, d.s, req),
      steps: [
        { type: 'say', lines: [[LENSES[l].npc, d.say]], ...(d.terms ? { terms: d.terms } : {}) },
        { type: 'num', id: `${id}_n`, concept: nc, q: SIM + nq, a: na, tol: ntol, unit: nunit, fb: replayFb(...nfb, review) },
        { type: 'quiz', id: `${id}_q`, concept: qc, q: qq, opts: qopts, a: qa, fb: replayFb(...qfb, review) },
      ],
      rewards: { xp: 25 },
    });
    REPLAY_IDS.push(id);
    quests[l] = id; map[l] = d.map;
  }
  REPLAYS[caseId] = { title: short, quests, roles, map };
}

